Node* node = root;
while (node) {
    // binary search for the first key >= target
    auto it = std::lower_bound(node->keys.begin(), node->keys.end(), key);
    // if exact match found in this node, key exists in the tree
    if (it != node->keys.end() && *it == key) {
        return true;
    }
    // if we are at a leaf, the key is not present
    if (node->leaf) {
        return false;
    }
    // determine child index to descend to
    std::size_t idx = static_cast<std::size_t>(std::distance(node->keys.begin(), it));
    node = node->children[idx];
}
return false;

